// Pot wiper -> A0, outer legs -> 5V and GND
// LED anode -> D9 via a 220R resistor, cathode -> GND

void setup() {
  Serial.begin(9600);
  pinMode(9, OUTPUT);
}

void loop() {
  int raw = analogRead(A0);   // 10-bit: 0..1023
  analogWrite(9, raw / 4);    // 8-bit PWM: 0..255
  Serial.println(raw);
  delay(50);
}

// Button between D2 and GND — the internal pull-up means no
// external resistor is needed.

const uint8_t BTN = 2;
bool on = false;
uint8_t last = HIGH;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  uint8_t now = digitalRead(BTN);
  if (last == HIGH && now == LOW) {   // falling edge = press
    on = !on;
    digitalWrite(LED_BUILTIN, on);
    delay(30);                        // crude debounce
  }
  last = now;
  delay(5);
}

