// SDA -> GPIO21, SCL -> GPIO22 (the ESP32 defaults)
#include <Wire.h>

void setup() {
  Serial.begin(115200);
  Wire.begin();
  for (uint8_t a = 1; a < 127; a++) {
    Wire.beginTransmission(a);
    if (Wire.endTransmission() == 0) {
      Serial.printf("device at 0x%02X\n", a);
    }
  }
  Serial.println("done");
}

void loop() {}

