// VCC -> 5V, GND -> GND, TRIG -> D9, ECHO -> D10
// On a 3.3V board, divide ECHO down first.

const uint8_t TRIG = 9, ECHO = 10;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
}

void loop() {
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  // Time out after ~30 ms so a missing echo does not block the loop.
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);
  if (us == 0) {
    Serial.println("no echo");
  } else {
    // Sound travels ~0.0343 cm/us; halve it for the round trip.
    Serial.print(us * 0.0343 / 2.0);
    Serial.println(" cm");
  }
  delay(100);
}

// ENA -> D9 (PWM), IN1 -> D8, IN2 -> D7
// Motor supply to +12V/GND terminals, GND shared with the Arduino.

const uint8_t ENA = 9, IN1 = 8, IN2 = 7;

void setup() {
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
}

void drive(int speed) {          // -255..255
  bool forward = speed >= 0;
  digitalWrite(IN1, forward);
  digitalWrite(IN2, !forward);
  analogWrite(ENA, abs(speed) > 255 ? 255 : abs(speed));
}

void loop() {
  drive(200);   delay(2000);   // forward
  drive(0);     delay(500);    // stop
  drive(-200);  delay(2000);   // reverse
  drive(0);     delay(500);
}

// VCC -> 5V, GND -> GND
// Module TXD -> D10 (Arduino RX)
// Module RXD -> D11 (Arduino TX) THROUGH A DIVIDER — the RXD pin
// is 3.3V logic and 5V straight into it will damage it over time.
#include <SoftwareSerial.h>

SoftwareSerial bt(10, 11);   // RX, TX

void setup() {
  Serial.begin(9600);
  bt.begin(9600);            // default baud on most HC-06 modules
  Serial.println("ready — pair, then type");
}

void loop() {
  if (bt.available())     Serial.write(bt.read());
  if (Serial.available()) bt.write(Serial.read());
}

// Left  motor: ENA -> D9,  IN1 -> D8,  IN2 -> D7
// Right motor: ENB -> D10, IN3 -> D6,  IN4 -> D5
// Motor supply to the L298N terminals; share GND with the Arduino.

const uint8_t ENA=9, IN1=8, IN2=7, ENB=10, IN3=6, IN4=5;

void setup() {
  for (uint8_t p : {ENA, IN1, IN2, ENB, IN3, IN4}) pinMode(p, OUTPUT);
}

void wheels(int left, int right) {   // -255..255 each
  digitalWrite(IN1, left  >= 0); digitalWrite(IN2, left  < 0);
  digitalWrite(IN3, right >= 0); digitalWrite(IN4, right < 0);
  analogWrite(ENA, min(abs(left), 255));
  analogWrite(ENB, min(abs(right), 255));
}

void loop() {
  wheels(180, 180);  delay(1500);   // forward
  wheels(180, -180); delay(600);    // spin
  wheels(0, 0);      delay(400);
}
